export const VariantPicker: React.FC<{
  onSelect?: (type: SmartBlockData_Type, isPreview?: boolean) => void;
  currentType?: SmartBlockData_Type;
  nodeId?: string;
}> = ({ onSelect, currentType, nodeId }) => {
  const { t, isMobile } = useContext(RicosContext);
  const { adapter } = useContext(EditorContext);
  const modals = useModalService();
  const converters = useConverters();
  const [searchValue, setSearchValue] = useState('');

  const enterTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const leaveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const previewingRef = useRef(false);
  const originalTypeRef = useRef(currentType);
  const selectedRef = useRef<HTMLDivElement | null>(null);
  // Keep a stable ref to onSelect so the cleanup effect can call it without re-subscribing
  const onSelectRef = useRef(onSelect);
  onSelectRef.current = onSelect;

  useEffect(() => {
    selectedRef.current?.scrollIntoView({ block: 'center' });
  }, []);

  useEffect(
    () => () => {
      if (enterTimerRef.current) {
        clearTimeout(enterTimerRef.current);
      }
      if (leaveTimerRef.current) {
        clearTimeout(leaveTimerRef.current);
      }
      // Revert any active preview when the modal closes (ESC, click-outside, close button)
      if (previewingRef.current && originalTypeRef.current && onSelectRef.current) {
        onSelectRef.current(originalTypeRef.current, true);
        previewingRef.current = false;
      }
    },
    []
  );

  const closeModal = () => modals?.closeModal(SMART_BLOCK_VARIANT_PICKER_MODAL_ID);

  const handleHoverEnter = (type: SmartBlockData_Type) => {
    if (!onSelect) {
      return;
    }
    if (leaveTimerRef.current) {
      clearTimeout(leaveTimerRef.current);
      leaveTimerRef.current = null;
    }
    if (enterTimerRef.current) {
      clearTimeout(enterTimerRef.current);
    }
    enterTimerRef.current = setTimeout(() => {
      enterTimerRef.current = null;
      previewingRef.current = true;
      onSelect(type, true);
    }, 300);
  };

  const handleHoverLeave = () => {
    if (enterTimerRef.current) {
      clearTimeout(enterTimerRef.current);
      enterTimerRef.current = null;
    }
    if (previewingRef.current && originalTypeRef.current && onSelect) {
      leaveTimerRef.current = setTimeout(() => {
        leaveTimerRef.current = null;
        previewingRef.current = false;
        onSelect(originalTypeRef.current!, true);
      }, 300);
    }
  };

  const translatedSections = useMemo(
    () =>
      VARIANT_SECTIONS.map(s => ({
        ...s,
        title: t(s.title),
        variants: s.variants.map(v => ({ ...v, label: t(v.label) })),
      })),
    [t]
  );

  const allTranslatedVariants = useMemo(
    () => translatedSections.flatMap(s => s.variants),
    [translatedSections]
  );

  const previewMap = useMemo(() => {
    let baseNodeJson: PmNodeJson | undefined;
    if (nodeId) {
      const tr = adapter.tiptapEditor.view.state.tr;
      const nodeWithPos = findNodeById(tr, nodeId)?.[0];
      baseNodeJson = nodeWithPos?.node.toJSON() as PmNodeJson | undefined;
    }

    return new Map(
      allTranslatedVariants.map(({ id, label, icon }) => [
        id,
        {
          id,
          label,
          icon,
          content: baseNodeJson
            ? (converters.fromPm({
                content: [applyTypeToNode(baseNodeJson, id)],
              }) as RicosDocument)
            : createSmartBlockTemplate(id, t),
        },
      ])
    );
  }, [nodeId, t, adapter, converters, allTranslatedVariants]);

  const filteredVariants = searchValue
    ? allTranslatedVariants.filter(v => v.label.toLowerCase().includes(searchValue.toLowerCase()))
    : [];

  const handleSelect = (type: SmartBlockData_Type) => {
    if (enterTimerRef.current) {
      clearTimeout(enterTimerRef.current);
      enterTimerRef.current = null;
    }
    if (leaveTimerRef.current) {
      clearTimeout(leaveTimerRef.current);
      leaveTimerRef.current = null;
    }
    previewingRef.current = false;
    if (onSelect) {
      onSelect(type);
    } else {
      const content = createSmartBlockTemplate(type, t);
      adapter.tiptapEditor.commands.insertSmartBlockPreset(content);
    }
    closeModal();
  };

  return (
    <Panel
      dataHook={DATA_HOOKS.INSERT_MODAL}
      closeButtonProps={{ onClick: closeModal }}
      maxHeight={isMobile ? undefined : 576}
    >
      <PanelHeader title={t('SmartBlock_Panel_Title')} />

      <Box paddingLeft="SP4" paddingRight="SP4" paddingBottom="SP3" paddingTop="SP3">
        <Search
          value={searchValue}
          onChange={e => setSearchValue(e.target.value)}
          onClear={() => setSearchValue('')}
          placeholder={t('SmartBlock_VariantPicker_SearchPlaceholder')}
          size="small"
        />
      </Box>

      {!searchValue && <Divider />}

      <Box
        overflowY="auto"
        direction="vertical"
        paddingBottom="SP4"
        style={{ flex: 1, minHeight: 0 }}
        className={classes.variantsBox}
      >
        {searchValue ? (
          <Box paddingLeft="SP4" paddingRight="SP4" paddingTop="SP1">
            <div className={classes.variantContainer}>
              {filteredVariants.map(v => {
                const variant = previewMap.get(v.id)!;
                return (
                  <div
                    key={variant.id}
                    ref={variant.id === currentType ? selectedRef : undefined}
                    onMouseOver={() => handleHoverEnter(variant.id)}
                    onMouseLeave={handleHoverLeave}
                  >
                    <LayoutThumbnail
                      image={<variant.icon />}
                      title={t(variant.label)}
                      selected={variant.id === currentType}
                      onClick={() => handleSelect(variant.id)}
                    />
                  </div>
                );
              })}
            </div>
          </Box>
        ) : (
          <Accordion
            hideShadow
            skin="light"
            size="medium"
            multiple
            dataHook="variant-accordion"
            items={translatedSections.map(section =>
              accordionItemBuilder({
                initiallyOpen: true,
                title: (
                  <Text size="small" weight="bold">
                    {section.title}
                  </Text>
                ),
                children: (
                  <div className={classes.variantContainer}>
                    {section.variants.map(v => {
                      const variant = previewMap.get(v.id)!;
                      return (
                        <div
                          key={variant.id}
                          ref={variant.id === currentType ? selectedRef : undefined}
                          onMouseOver={() => handleHoverEnter(variant.id)}
                          onMouseLeave={handleHoverLeave}
                        >
                          <LayoutThumbnail
                            image={<variant.icon />}
                            title={t(variant.label)}
                            selected={variant.id === currentType}
                            onClick={() => handleSelect(variant.id)}
                          />
                        </div>
                      );
                    })}
                  </div>
                ),
              })
            )}
          />
        )}
      </Box>
    </Panel>
  );
};

const LayoutThumbnail: React.FC<React.ComponentProps<typeof Thumbnail>> = props => {
  return (
    <Thumbnail
      height={120}
      width={117}
      size="tiny"
      contentAlignment="center"
      textPosition="outside"
      {...props}
    />
  );
};

const applyTypeToNode = (pmJson: PmNodeJson, type: SmartBlockData_Type): PmNodeJson => {
  const oldType = pmJson.attrs?.type as SmartBlockData_Type | undefined;
  const result: PmNodeJson = { ...pmJson, attrs: { ...pmJson.attrs, type } };

  if (result.content) {
    result.content = result.content.map(cell => {
      if (cell.type !== PmNodeType.SMART_BLOCK_CELL) {
        return cell;
      }
      const newColorAttr = getCellColorAttr(type);
      const newAttrs: Record<string, unknown> = { ...cell.attrs, type };
      if (oldType) {
        const oldColorAttr = getCellColorAttr(oldType);
        if (oldColorAttr !== newColorAttr) {
          newAttrs[newColorAttr] = cell.attrs?.[oldColorAttr];
          newAttrs[oldColorAttr] = null;
        }
      }
      const isStatVariant = type === 'CIRCLE_STATS' || type === 'BAR_STATS' || type === 'STATS';
      if (isStatVariant && !cell.attrs?.label) {
        newAttrs.label = DEFAULT_LABEL;
      } else if (type === 'STAR_RATING' && !cell.attrs?.label) {
        newAttrs.label = DEFAULT_STAR_RATING_LABEL;
      }
      return { ...cell, attrs: newAttrs };
    });
  }

  return result;
};
