import { Input } from '@wix/design-system';
import type { FC } from 'react';
import React, { useContext, useEffect, useMemo, useRef } from 'react';

import {
  EditorContext,
  ModalServiceContext,
  RicosContext,
  ZIndexContext,
} from './../../ricos-context/index.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import { TRANSPARENT_HEX_COLOR } from './../../_shared/colors.js';
import type { PmSmartBlockNode } from './../../_shared/pm-node-types.js';
import { PmNodeType } from './../../_shared/pm-node-types.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';
import { findParentNodeClosestToPos } from './../../tiptap/core/index.js';
import type { Node as PmNode } from './../../tiptap/pm/model.js';
import {
  ColorWithOpacityInput,
  NumberInputWithLabel,
  Panel,
  PanelHeader,
} from './../../ui-components/index.js';
import { findNodeById } from './../../tiptap-editor/helpers/index.js';

import { DATA_HOOKS } from '../data-hooks.js';
import { resolveThemeSmartBlock } from '../utils/resolve-theme-smart-block.js';
import { hasBlockBorderSupport } from '../utils/variant-features.js';
import { ColorPicker } from './color-picker.js';

export const SMART_BLOCK_BORDER_SETTINGS_MODAL_ID = 'smart-block-border-settings-modal';
export const SMART_BLOCK_BORDER_COLOR_PICKER_MODAL_ID = 'smart-block-border-color-picker-modal';

export const BorderSettings: FC<{ nodeId?: string }> = ({ nodeId }) => {
  const { isMobile } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext);
  const { adapter } = useContext(EditorContext);

  const { borderColor, borderWidth, borderRadius, colorFills, colorPickerNodeId, applyDesign } =
    useBlockBorderSettings(nodeId);

  // Refs so callbacks always use the latest values without stale closures
  const borderWidthRef = useRef(borderWidth);
  const borderRadiusRef = useRef(borderRadius);
  useEffect(() => {
    borderWidthRef.current = borderWidth;
  }, [borderWidth]);
  useEffect(() => {
    borderRadiusRef.current = borderRadius;
  }, [borderRadius]);

  const logBi = useBiNext({
    modalId: SMART_BLOCK_BORDER_SETTINGS_MODAL_ID,
    pluginId: 'smartBlock',
    nodeId,
  });

  const openColorPicker = (referenceElement: HTMLDivElement) => {
    if (!colorPickerNodeId) {
      return;
    }
    // Clear the live preview whenever the picker closes by any path (click-outside,
    // Escape, X, programmatic) — onColorPreviewEnd only fires for the X button.
    const closeSub = modalService.onModalClosed(modal => {
      if (modal.id === SMART_BLOCK_BORDER_COLOR_PICKER_MODAL_ID) {
        adapter.tiptapEditor.commands.clearSmartBlockColorPreview();
        closeSub.cancel();
      }
    });
    modalService.togglePluginPanel({
      id: SMART_BLOCK_BORDER_COLOR_PICKER_MODAL_ID,
      Component: ColorPicker,
      componentProps: {
        modalId: SMART_BLOCK_BORDER_COLOR_PICKER_MODAL_ID,
        nodeId: colorPickerNodeId,
        colorAttr: 'borderColor' as const,
        referenceElement,
        // Preview during drag (no doc change → no undo entries); commit once on release.
        onColorPreview: (color: string | undefined) => {
          adapter.tiptapEditor.commands.setSmartBlockColorPreview({ attr: 'borderColor', color });
        },
        onColorPreviewEnd: () => {
          adapter.tiptapEditor.commands.clearSmartBlockColorPreview();
        },
        onColorSelected: (color: string | undefined) => {
          adapter.tiptapEditor.commands.clearSmartBlockColorPreview();
          if (color === undefined) {
            // Reset: clear the explicit color so the viewer falls back to the theme default.
            applyDesign({ borderColor: null });
            return;
          }
          applyDesign({
            borderColor: color,
            borderWidth: borderWidthRef.current === 0 ? 1 : borderWidthRef.current,
            borderRadius: borderRadiusRef.current,
          });
        },
      },
      isMobile,
      positioning: { referenceElement, placement: 'left' },
      onClickOutside: { on: 'pointerup', handler: () => {} },
      focusReturnElement: referenceElement,
      type: undefined,
    });
  };

  const closePanel = () => {
    modalService.closeModal(SMART_BLOCK_BORDER_COLOR_PICKER_MODAL_ID);
    modalService.closeModal(SMART_BLOCK_BORDER_SETTINGS_MODAL_ID);
  };

  const handleColorChangeCommit = (color: string | undefined) => {
    if (color === undefined) {
      applyDesign({ borderColor: null });
      return;
    }
    applyDesign({
      borderColor: color,
      borderWidth: borderWidthRef.current === 0 ? 1 : borderWidthRef.current,
      borderRadius: borderRadiusRef.current,
    });
  };

  return (
    <BorderSettingsForm
      borderColor={borderColor}
      borderWidth={borderWidth}
      borderRadius={borderRadius}
      colorFills={colorFills}
      logBi={logBi}
      onColorChangeCommit={handleColorChangeCommit}
      onColorPress={openColorPicker}
      onWidthChange={value => applyDesign({ borderWidth: value ?? 0 })}
      onRadiusChange={value => applyDesign({ borderRadius: value ?? 0 })}
      onClose={closePanel}
    />
  );
};

type BorderSettingsFormProps = {
  borderColor: string;
  borderWidth: number;
  borderRadius: number;
  colorFills?: string[];
  logBi: ReturnType<typeof useBiNext>;
  onColorChangeCommit: (color: string | undefined) => void;
  onColorPress: (ref: HTMLDivElement) => void;
  onWidthChange: (value: number | undefined) => void;
  onRadiusChange: (value: number | undefined) => void;
  onClose: () => void;
};

const BorderSettingsForm: FC<BorderSettingsFormProps> = ({
  borderColor,
  borderWidth,
  borderRadius,
  colorFills,
  logBi,
  onColorChangeCommit,
  onColorPress,
  onWidthChange,
  onRadiusChange,
  onClose,
}) => {
  const colorPickerRef = useRef<HTMLDivElement>(null);
  const zIndex = useContext(ZIndexContext).getZIndex('DIALOG');
  const { t } = useContext(RicosContext);

  return (
    <Panel closeButtonProps={{ onClick: onClose }} dataHook={DATA_HOOKS.BLOCK_BORDER_SETTINGS}>
      <PanelHeader title={t('SmartBlock_BorderSettings_Title')} />
      <div style={{ padding: '12px 20px', display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <ColorWithOpacityInput
          label={t('SmartBlock_BorderSettings_BorderColor')}
          fill={
            colorFills && colorFills.length > 1
              ? { type: 'multi-color', colors: colorFills }
              : {
                  type: 'color',
                  color: borderColor,
                  onChangeCommit: onColorChangeCommit,
                  allowTransparent: true,
                }
          }
          onColorPress={() => onColorPress(colorPickerRef.current!)}
          colorPickerRef={colorPickerRef}
          inputDataHook={DATA_HOOKS.CELL_DESIGN_BORDER_COLOR}
          fillPreviewDataHook={DATA_HOOKS.CELL_DESIGN_BORDER_COLOR_PICKER}
          zIndex={zIndex}
          logBi={logBi}
        />

        <NumberInputWithLabel
          label={t('SmartBlock_BorderSettings_BorderWidth')}
          dataHook={DATA_HOOKS.CELL_DESIGN_BORDER_WIDTH}
          suffix={<Input.Affix>{'px'}</Input.Affix>}
          value={borderWidth}
          min={0}
          max={15}
          onChange={onWidthChange}
          logBi={logBi}
          zIndex={zIndex}
        />

        <NumberInputWithLabel
          label={t('SmartBlock_BorderSettings_CornerRadius')}
          dataHook={DATA_HOOKS.CELL_DESIGN_BORDER_RADIUS}
          suffix={<Input.Affix>{'px'}</Input.Affix>}
          value={borderRadius}
          min={0}
          max={30}
          onChange={onRadiusChange}
          logBi={logBi}
          zIndex={zIndex}
        />
      </div>
    </Panel>
  );
};

const useBlockBorderSettings = (nodeId: string | undefined) => {
  const { adapter } = useContext(EditorContext);
  const { theme } = useContext(RicosContext);
  const { pmNodeAttrs } = useNodeAttrs(nodeId ?? '', PmNodeType.SMART_BLOCK_CELL);

  // When borderWidth > 0 without an explicit borderColor, the rendered border
  // falls back to the theme's smart-block borderColor. Surface that same color
  // in the swatch so the modal matches what the user sees on the canvas.
  const themeBorderColor = useMemo(() => resolveThemeSmartBlock(theme)?.borderColor, [theme]);

  const parentSmartBlock = useMemo(() => {
    const { selection } = adapter.tiptapEditor.state;
    // Handle NodeSelection on the smart block itself (via "Select Block" button)
    const nodeSelection = selection as { node?: PmNode };
    if (nodeSelection.node?.type?.name === PmNodeType.SMART_BLOCK) {
      return { node: nodeSelection.node, pos: selection.from, depth: 0, start: selection.from + 1 };
    }
    return findParentNodeClosestToPos(
      adapter.tiptapEditor.state.doc.resolve(selection.from),
      node => node.type?.name === PmNodeType.SMART_BLOCK
    );
  }, [adapter.tiptapEditor.state]);

  const { design, colorFills, colorPickerNodeId } = useMemo(() => {
    if (!parentSmartBlock || parentSmartBlock.node.childCount === 0) {
      return { design: null, colorFills: [] as string[], colorPickerNodeId: undefined };
    }

    const { node } = parentSmartBlock;

    if (hasBlockBorderSupport(node.attrs.type)) {
      const attrs = node.attrs as PmSmartBlockNode['attrs'];
      return {
        design: {
          borderColor: attrs.borderColor ?? undefined,
          borderWidth: attrs.borderWidth ?? undefined,
          borderRadius: attrs.borderRadius ?? undefined,
        },
        colorFills: attrs.borderColor ? [attrs.borderColor] : [],
        colorPickerNodeId: attrs.id,
      };
    }

    const borderColorSet = new Set<string>();
    node.forEach((child: PmNode) => {
      const bc = child.attrs.borderColor;
      if (bc) {
        borderColorSet.add(bc);
      }
    });

    return {
      design: {
        borderColor: allSame(node, 'borderColor') as string | undefined,
        borderWidth: allSame(node, 'borderWidth') as number | undefined,
        borderRadius: allSame(node, 'borderRadius') as number | undefined,
      },
      colorFills: [...borderColorSet],
      colorPickerNodeId: node.firstChild?.attrs.id as string | undefined,
    };
  }, [parentSmartBlock]);

  // Cell mode
  if (nodeId) {
    return {
      borderColor: pmNodeAttrs?.borderColor ?? themeBorderColor ?? TRANSPARENT_HEX_COLOR,
      borderWidth: pmNodeAttrs?.borderWidth ?? 0,
      borderRadius: pmNodeAttrs?.borderRadius ?? 0,
      colorPickerNodeId: nodeId,
      applyDesign: (updates: {
        borderColor?: string | null;
        borderWidth?: number;
        borderRadius?: number;
      }) =>
        adapter.tiptapEditor.commands.command(({ tr }) => {
          const nodeWithPos = findNodeById(tr, nodeId)[0];
          if (!nodeWithPos) {
            return false;
          }
          Object.entries(updates).forEach(([key, value]) => {
            tr.setNodeAttribute(nodeWithPos.pos, key, value);
          });
          return true;
        }),
    };
  }

  return {
    borderColor: design?.borderColor ?? themeBorderColor ?? TRANSPARENT_HEX_COLOR,
    borderWidth: design?.borderWidth ?? 0,
    borderRadius: design?.borderRadius ?? 0,
    colorFills,
    colorPickerNodeId,
    applyDesign: (updates: {
      borderColor?: string | null;
      borderWidth?: number;
      borderRadius?: number;
    }) => adapter.tiptapEditor.commands.applyDesignToAllCells(updates),
  };
};

const allSame = (node: PmNode, key: 'borderColor' | 'borderWidth' | 'borderRadius') => {
  const firstVal = node.firstChild?.attrs[key];
  let same = true;
  node.forEach((child: PmNode) => {
    if (child.attrs[key] !== firstVal) {
      same = false;
    }
  });
  return same ? (firstVal ?? undefined) : undefined;
};
