import type { FC } from 'react';
import React, { useContext, useMemo } from 'react';

import { ModalServiceContext, RicosContext } from './../../ricos-context/index.js';
import type { SmartBlockData_Type } from './../../ricos-schema/next-schema/index.js';
import { mapColorPaletteToCustomStyles } from './../../ricos-styles/themeStrategy/generators/palette.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import {
  handleColorAdded as addColorToManager,
  handleColorDeleted,
  resolveThemeColorsPalette,
  useResolvedCustomColors,
} from './../../_shared/color-manager-utils.js';
import { TRANSPARENT_HEX_COLOR } from './../../_shared/colors.js';
import { PmNodeType } from './../../_shared/pm-node-types.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';
import { NewColorPicker } from './../../ui-components/color-picker/new-color-picker/index.js';

import { getCellColorAttr } from '../utils/variant-features.js';

type ColorAttr = 'backgroundColor' | 'accentColor' | 'shapeColor' | 'borderColor';

type ColorPickerProps = {
  modalId: string;
  nodeId: string;
  colorAttr: ColorAttr;
  variant?: SmartBlockData_Type;
  referenceElement: HTMLElement | undefined;
  onColorSelected: (color: string | undefined) => void;
  // Providing onColorPreview flips the picker into deferred-commit mode: it
  // previews on every drag frame and commits (onColorSelected) once on release.
  onColorPreview?: (color: string | undefined) => void;
  onColorPreviewEnd?: () => void;
};

export const ColorPicker: FC<ColorPickerProps> = ({
  modalId,
  nodeId,
  colorAttr,
  variant,
  referenceElement,
  onColorSelected,
  onColorPreview,
  onColorPreviewEnd,
}) => {
  const modalService = useContext(ModalServiceContext);
  const { t, colorManager, theme } = useContext(RicosContext);

  const themeColors = useMemo(() => resolveThemeColorsPalette(theme), [theme]);
  const customColors = useResolvedCustomColors(colorManager);

  const { pmNodeAttrs: cellNodeAttrs } = useNodeAttrs(nodeId, PmNodeType.SMART_BLOCK_CELL);
  // For variants where the border lives on the block itself (e.g. SOLID_JOINED_BOXES),
  // border-settings passes the block's nodeId rather than a cell's. Fall back to the block
  // node attrs so the picker reflects the live border color in that case.
  const { pmNodeAttrs: blockNodeAttrs } = useNodeAttrs(nodeId, PmNodeType.SMART_BLOCK);

  const themeSmartBlock = useMemo(
    () =>
      theme?.customStyles?.smartBlock ??
      (theme?.colorPalette
        ? mapColorPaletteToCustomStyles(theme.colorPalette).smartBlock
        : undefined),
    [theme?.customStyles?.smartBlock, theme?.colorPalette]
  );

  // Live color from node attrs; fall back to theme default when no explicit color is stored.
  // shapeColor uses labelColor as its theme default; all others use the variant color attr.
  const liveColor =
    cellNodeAttrs?.[colorAttr] ??
    (colorAttr === 'borderColor' ? blockNodeAttrs?.borderColor : undefined);
  const themeDefault = useMemo(() => {
    if (!themeSmartBlock) {
      return undefined;
    }
    if (colorAttr === 'shapeColor') {
      return themeSmartBlock.labelColor;
    }
    if (colorAttr === 'borderColor') {
      return themeSmartBlock.borderColor;
    }
    return variant ? themeSmartBlock[getCellColorAttr(variant)] : undefined;
  }, [colorAttr, variant, themeSmartBlock]);

  const resolvedColor = liveColor ?? themeDefault ?? TRANSPARENT_HEX_COLOR;

  const logBi = useBiNext({
    modalId,
    pluginId: 'smartBlock',
    nodeId,
  });

  const onColorAdded = (color: string) => {
    addColorToManager(color, colorManager);
    onColorSelected(color);
  };

  const onColorDeletedHandler = (color: string) => {
    handleColorDeleted(color, colorManager);
  };

  const closeModal = () => modalService.closeModal(modalId);

  return (
    <NewColorPicker
      themeColors={themeColors}
      customColors={customColors}
      currentColor={resolvedColor}
      title={t('Layouts_ColourModal_Title')}
      closeModal={closeModal}
      onColorSelected={onColorSelected}
      onColorPreview={onColorPreview}
      onColorPreviewEnd={onColorPreviewEnd}
      onColorAdded={onColorAdded}
      onColorDeleted={onColorDeletedHandler}
      onResetColor={() => onColorSelected(undefined)}
      referenceElement={referenceElement}
      allowTransparent
      logBi={logBi}
    />
  );
};
